-- ELEMENT_METHODS (4 CBET stages per lesson)
-- Methods: 1=Demonstration 2=Group Discussion 3=Q&A 4=Hands-on
--          5=Brainstorming 6=TIPS 7=Case Study 8=Project Based
--          9=Practical 10=Role Play 12=Research Based
-- Double period (80 min): intro=10, development=40, design=20, realisation=10
-- Single period (40 min): intro=5, development=20, design=10, realisation=5
-- --------------------------------------------------------
INSERT INTO `element_methods` (`element_id`,`method_id`,`stage`,`time_minutes`,`teaching_activity`,`learning_activity`,`assessment_criteria`) VALUES
-- Lesson 1001 :: 1.1(a)-L01 :: Safety procedures and electrostatic discharge precautions
(1001,3,'introduction',10,
 'Ask students to state the tasks they would perform to achieve safety procedures and ESD precautions when handling hardware using the equipment in the laboratory.',
 'State the tasks needed to achieve safety procedures and ESD precautions when handling hardware using the available equipment.',
 'Tasks needed for safety procedures and ESD precautions when handling hardware are stated.'),
(1001,1,'development',40,
 'Demonstrate safety procedures and ESD precautions when handling hardware step by step on the computer using the projector, stating the purpose of each step.',
 'Observe the demonstration, note each step and repeat the steps on their own computers.',
 'The steps of safety procedures and ESD precautions when handling hardware are correctly performed.'),
(1001,9,'design',20,
 'Assign each pair a practical task on safety procedures and ESD precautions when handling hardware to be completed on the computer, and supervise the work.',
 'Complete the assigned practical task on safety procedures and ESD precautions when handling hardware on the computer.',
 'The practical task on safety procedures and ESD precautions when handling hardware is correctly completed.'),
(1001,3,'realisation',10,
 'Ask each student to demonstrate one step of safety procedures and ESD precautions when handling hardware on the computer.',
 'Demonstrate one step of safety procedures and ESD precautions when handling hardware on the computer.',
 'One step of safety procedures and ESD precautions when handling hardware is correctly demonstrated by each student.'),
-- Lesson 1002 :: 1.1(a)-L02 :: Identification of computer hardware components and their functions
(1002,5,'introduction',10,
