 'List the steps of debugging of problems arising when accessing arrays in the correct order.',
 'The steps of debugging of problems arising when accessing arrays are listed in the correct order.'),
-- Lesson 1267 :: 2.4(b)-L16 :: Integrated practice: an array processing project [single period 40 min]
(1267,1,'introduction',5,
 'Display the tools and the working environment needed for developing a complete program that processes an array and ask students to name each one and its use.',
 'Name the tools and environment needed for developing a complete program that processes an array and state the use of each.',
 'Tools needed for developing a complete program that processes an array are named with their uses.'),
(1267,1,'development',20,
 'Demonstrate developing a complete program that processes an array and then guide students to repeat the demonstration while explaining what they are doing.',
 'Repeat the demonstration of developing a complete program that processes an array while explaining each step performed.',
 'Developing a complete program that processes an array is correctly demonstrated and explained.'),
(1267,8,'design',10,
 'Guide groups to plan and start a small project applying developing a complete program that processes an array, and to record the steps followed.',
 'In groups, plan and start a small project applying developing a complete program that processes an array and record the steps followed.',
 'A small project applying developing a complete program that processes an array is correctly planned and started.'),
(1267,4,'realisation',5,
 'Give a short practical check on developing a complete program that processes an array to be completed individually within the remaining time.',
 'Complete the short practical check on developing a complete program that processes an array individually.',
 'The practical check on developing a complete program that processes an array is correctly completed.');

